let windowSize = 2h;

// S58: Archive Supply-Chain (Zip Slip) — UAVArchiveAudit_CL엔 Operator/UAVId 없음, 전역 게이트
let S58Time = toscalar(
    UAVArchiveAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where PathTraversalDetected == true
    | summarize min(TimeGenerated));

// S92: Exfil (SAR/Auth) — UAVSarPayload_CL엔 Operator 없음, 전역 게이트
let S92Time = toscalar(
    UAVSarPayload_CL
    | where TimeGenerated > ago(windowSize)
    | where SizeBytes > 0
    | summarize min(TimeGenerated));

// S54: Webshell Upload (연결키: Operator — UAVWebAudit_CL RequesterId 사용)
let S54 =
    UAVWebAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where WebshellSignatureDetected == true
    | project TimeGenerated, Operator = tostring(RequesterId)
    | where isnotempty(Operator);

S54
| extend HasS58 = isnotnull(S58Time), HasS92 = isnotnull(S92Time)
| where HasS58 or HasS92
| extend CampaignType = "C17_아카이브전달_웹셸_SAR유출"
| extend StepSummary = strcat("S58(전역)@", tostring(S58Time), " | S54@", tostring(TimeGenerated), " | S92(전역)@", tostring(S92Time))
| extend Severity = "High"
| project TimeGenerated, S58Time, S92Time, Operator, CampaignType, StepSummary, Severity
